/* ---------- 別スレッド（Web Worker）で作る ---------- */
// 取り出し・取り込み（同じ形のデータを主スレッドへ渡す）
GEO.TA_KEYS = ['E', 'Wt', 'wE', 'loess', 'steppe', 'rough', 'waterDist', 'seaDist', 'M', 'SAND', 'MARSHR', 'LOES', 'STEP', 'reg', 'popField'];
